pub fn resolve_embed_url(cfg_url: &str, env: Option<&str>, tunnel_port: u16) -> Result<String> {
    let (url, from) = match env.map(str::trim).filter(|v| !v.is_empty()) {
        Some(v) => (v, EMBED_URL_ENV),
        None => (cfg_url.trim(), "embed_url"),
